            if int(I[i][j])!=bg:
                da[i+j].append((i,j)); dm[i-j].append((i,j))
    def extend(pts,name):
        # pts is a list of tuples (i,j) on one diagonal, consecutive, sorted by i
        cols={int(I[p[0]][p[1]]) for p in pts}
